// 隔离共享候选：真实原Office授权到柜台接任，Role和永久结果始终留同一个玩家候选。
#include "political_office_reception_world.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
// 空账也不能跳过原作者公署辖区，目录/seed必须严格成对选择。
Status available(const WorldBundle& w){if(!w.catalog->political_office_receptions||!w.political_office_receptions||!w.catalog->political_successions||!w.political_successions||!w.politics_enabled()||!w.catalog->organization||!w.catalog->organization->enabled||!w.family_life_enabled()||!w.catalog->common)return common_failure("PoliticalOfficeReceptionProfileRequired");for(const auto& row:w.catalog->political_office_receptions->policies.rows()){const auto* p=w.catalog->political_successions->policies.find(row.second.succession_policy_id);const auto* j=p?w.catalog->politics->jurisdictions.find(p->jurisdiction_id):nullptr;if(!p||!j||j->revision!=0||j->office_id!=p->leader_office_id||j->seat_place_id!=p->seat_place_id||j->political_organization_id!=p->organization_id||j->controlling_organization_id!=p->organization_id)return common_failure("PoliticalOfficeReceptionOriginalSeatRequired",row.first);}return common_success();}
// 实际成功明细只含该次岗位事实，不接受Office变更或任命结果伪装为岗位移交。
bool actual_result(const CommitResult& r,const StableId& source){if(!r.ok||!r.details)return false;const auto* e=std::get_if<PoliticsEffects>(&r.details->data);return e&&valid_political_office_reception_effect(r.kind,*e)&&e->fact_ids==std::vector<StableId>{source};}
// 本人身份不旁路原生命/行动/舟上共同守卫；两个NPC提交入口另在保存点之前拒绝。
Status player(const WorldBundle& w,const StableId& actor,const PoliticalOfficeReceptionCommand& c){auto v=command_common_guard(w,actor,political_office_reception_command_kind(c));if(!v.ok)return v;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("PoliticalOfficeReceptionPlayerCommandRequired");}
}
// 同一holder按声明顺序持有军事/占领/座所源，回调只在其短栈生命周期内同步消费。
PoliticalOfficeReceptionWorldAccess::PoliticalOfficeReceptionWorldAccess(const WorldBundle& w):world_(w),military_(w.political_takeover_enabled()?std::optional<MilitaryAccess>{w.services.military_access()}:std::nullopt),occupations_(w.political_takeover_enabled()?std::optional<PoliticalSuccessionOccupationContext>{PoliticalSuccessionOccupationContext{w.political_takeover,*w.catalog->political_takeover,w.military,*w.catalog->military,*military_}}:std::nullopt),territory_{w.common,w.politics,*w.catalog->politics,occupations_?&*occupations_:nullptr},rules_{w.common,*w.catalog->common,w.organization,*w.catalog->organization,w.local_economy,w.services,*w.catalog->political_successions,*w.catalog->political_office_receptions,*w.political_office_receptions,w.family_death_read(),[this](const PoliticalSuccessionPolicy& p,Integer tick,const StableId& fact){return validate_political_office_reception_seat(territory_,p,tick,fact);},[&w](Integer tick,const StableId& fact){return read_political_office_reception_player_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);}},context_{rules_,actual_result}{}
Outcome<std::unique_ptr<PoliticalOfficeReceptionWorldAccess>> PoliticalOfficeReceptionWorldAccess::create(const WorldBundle& w){auto valid=available(w);if(!valid.ok)return {false,{},valid.error};return {true,std::unique_ptr<PoliticalOfficeReceptionWorldAccess>{new PoliticalOfficeReceptionWorldAccess(w)},{}};}
// 位于完整Organization/原政治/Family生命与控制史后，原Role不因启用空账而默迁移。
Status validate_political_office_reception_world(const WorldBundle& w){auto v=validate_political_office_reception_layout(w.common,w.catalog->identity.module_versions,w.political_office_receptions?&*w.political_office_receptions:nullptr);if(!v.ok)return v;if(bool(w.catalog->political_office_receptions)!=w.political_office_receptions.has_value())return common_failure("PoliticalOfficeReceptionProfileMismatch");if(!w.catalog->political_office_receptions)return common_success();auto read=PoliticalOfficeReceptionWorldAccess::create(w);return read.ok?validate_political_office_receptions(read.value->context()):Status{false,{},read.error};}
Outcome<PoliticalOfficeReceptionQuote> prepare_political_office_reception_world(const WorldBundle& w,const StableId& actor,const PoliticalOfficeReceptionCommand& c){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto read=PoliticalOfficeReceptionWorldAccess::create(w);return read.ok?preview_political_office_reception_business(read.value->context(),actor,c):Outcome<PoliticalOfficeReceptionQuote>{false,{},read.error};}
Outcome<PoliticsEffects> commit_political_office_reception_world(WorldBundle& w,const StableId& actor,const PoliticalOfficeReceptionCommand& c,const PoliticalOfficeReceptionQuote& q){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto read=PoliticalOfficeReceptionWorldAccess::create(w);if(!read.ok)return {false,{},read.error};auto source=apply_political_office_reception_business_in_candidate(w.common,*w.political_office_receptions,read.value->context(),actor,c,q);return source.ok?Outcome<PoliticsEffects>{true,{{},{source.value},{}},{}}:Outcome<PoliticsEffects>{false,{},source.error};}
Outcome<BoundaryValue> query_political_office_reception_world(const WorldBundle& w,const StableId& place,Integer cursor){auto read=PoliticalOfficeReceptionWorldAccess::create(w);return read.ok?query_political_office_receptions(read.value->context(),place,cursor):Outcome<BoundaryValue>{false,{},read.error};}
Status bind_political_office_reception_result_world(WorldBundle& w,const StableId& source,const StableId& actor,Integer request,const CommitResult& result){if(!w.catalog->political_office_receptions||!w.political_office_receptions||source.empty()||!is_political_office_reception_command(result.kind))return common_failure("PoliticalOfficeReceptionNewSourceRequired");return bind_political_office_reception_player_result(w.common,*w.political_office_receptions,source,actor,request,result,actual_result);}
}
